const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-122.107805, 39.493523]);
  const radiusMeters = 10 * 1609.34; // 10 miles to meters
  const geometry = point.buffer(radiusMeters);

  const date1 = '2021-09-04';
  const date2 = '2022-09-16';
  const toleranceDays = 5; // Allow ±5 days for cloud-free image

  // 2. Data Acquisition & Cloud Masking
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function getNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  function getImageForDate(targetDate, collection) {
    const startDate = ee.Date(targetDate).advance(-toleranceDays, 'day');
    const endDate = ee.Date(targetDate).advance(toleranceDays, 'day');

    return collection
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .map(maskS2clouds)
      .map(getNDVI)
      .median();
  }

  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  // Get images for both dates
  const img1 = getImageForDate(date1, s2);
  const img2 = getImageForDate(date2, s2);

  // Check if collections are empty
  const count1 = s2.filterDate(ee.Date(date1).advance(-toleranceDays, 'day'), 
                              ee.Date(date1).advance(toleranceDays, 'day'))
                   .filterBounds(geometry).size().getInfo();
  const count2 = s2.filterDate(ee.Date(date2).advance(-toleranceDays, 'day'), 
                              ee.Date(date2).advance(toleranceDays, 'day'))
                   .filterBounds(geometry).size().getInfo();

  console.log(`2021 Images: ${count1}, 2022 Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI and pixel counts
  const reducer = ee.Reducer.mean().combine(ee.Reducer.count(), '', true);

  const stats1 = img1.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = img2.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const ndvi1 = stats1.NDVI;
  const ndvi2 = stats2.NDVI;
  const pixels1 = stats1.NDVI_count;
  const pixels2 = stats2.NDVI_count;

  console.log(`2021 NDVI: ${ndvi1?.toFixed(3)}, Pixels: ${pixels1}`);
  console.log(`2022 NDVI: ${ndvi2?.toFixed(3)}, Pixels: ${pixels2}`);

  // 4. Validation & Final Answer
  if (pixels1 === 0 || pixels2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (ndvi1 === null || ndvi2 === null || 
      Math.abs(ndvi1) > 1 || Math.abs(ndvi2) > 1 ||
      isNaN(ndvi1) || isNaN(ndvi2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  const ndviChange = ndvi2 - ndvi1;
  console.log(`NDVI Change: ${ndviChange.toFixed(3)}`);

  if (ndviChange < 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
